from typing import Any, Dict
from copy import deepcopy

def deep_merge(a: Dict[Any, Any], b: Dict[Any, Any]) -> Dict[Any, Any]:
    """Recursively merge dict b into a (b wins on leaf conflicts).

    Args:
        a: Base dict; not mutated.
        b: Dict to merge on top.

    Returns:
        A new dict with nested dicts merged recursively.

    Examples:
        >>> a = {"x": {"y": 1, "z": 2}}; b = {"x": {"y": 99}, "w": 7}
        >>> deep_merge(a, b)
        {'x': {'y': 99, 'z': 2}, 'w': 7}
        >>> deep_merge({}, {})
        {}
    """
    out: Dict[Any, Any] = dict(a)
    for k, v in b.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = deepcopy(v) if isinstance(v, (dict, list)) else v
    return out

from typing import Any, Dict, Iterator

class CountDict:
    """A dict-like mapping where missing keys yield zero.

    Examples:
        >>> c = CountDict({"a": 3})
        >>> c["a"]
        3
        >>> c["missing"]
        0
        >>> "missing" in c
        False
    """
    def __init__(self, data: Dict[str, int] = None) -> None:
        self._data: Dict[str, int] = dict(data) if data else {}

    def __getitem__(self, key: str) -> int:
        return self._data.get(key, 0)

    def __setitem__(self, key: str, value: int) -> None:
        self._data[key] = value

    def __contains__(self, key: str) -> bool:
        return key in self._data

    def __iter__(self) -> Iterator[str]:
        return iter(self._data)

    def __repr__(self) -> str:
        return f"CountDict({self._data!r})"

