from typing import Any, Dict

class WordCounter:
    """A counter specialized for counting words in a string."""
    def __init__(self) -> None:
        self._c: Dict[str, int] = {}

    def add_text(self, text: str) -> None:
        for w in text.split():
            self._c[w] = self._c.get(w, 0) + 1

    def count_of(self, word: str) -> int:
        """Number of occurrences of word.

        Examples:
            >>> c = WordCounter(); c.add_text('a b a'); c.count_of('a')
            2
        """
        return self._c.get(word, 0)

    def most_common(self, n: int) -> list:
        if n < 0:
            raise ValueError("n must be >= 0")
        return sorted(self._c.items(), key=lambda kv: -kv[1])[:n]

if __name__ == "__main__":
    c = WordCounter()
    c.add_text("the quick brown fox jumps over the lazy dog the")
    print(c.most_common(2))

