class SparseList:
    """A sparse list storing only the populated indices.

    Examples:
        >>> s = SparseList()
        >>> s.set(3, 'a'); s.set(7, 'b')
        >>> s.get(3)
        'a'
        >>> s.get(7)
        'b'
        >>> s.get(0) is None
