from typing import List

def bucket_sort(values: List[int]) -> List[int]:
    """Sort non-negative integers using bucket sort.

    Args:
        values: A list of non-negative integers.

    Returns:
        A new list sorted in non-decreasing order.

    Examples:
        >>> bucket_sort([29, 25, 3, 49, 9, 37, 21, 43])
        [3, 9, 21, 25, 29, 37, 43, 49]
        >>> bucket_sort([])
        []
    """
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if not values:
        return []
    if any(v < 0 for v in values):
        raise ValueError("bucket_sort only handles non-negative integers")
    if len(values) == 1:
        return list(values)
    lo, hi = min(values), max(values)
    if lo == hi:
        return list(values)
    bucket_count = len(values)
    buckets: List[List[int]] = [[] for _ in range(bucket_count)]
    for v in values:
        idx = (v - lo) * (bucket_count - 1) // (hi - lo)
        buckets[idx].append(v)
    out: List[int] = []
    for b in buckets:
        out.extend(sorted(b))
    return out

We compare character frequencies. A window of length equal to the pattern slides over the text; for each position we maintain a count of matches between the window's character frequencies and the pattern's. We use two dicts and increment or decrement a counter of matched character types as the window moves. When the match counter equals the number of distinct pattern characters we have found a permutation.

