from typing import Callable, Any, List

class CountingEmitter:
    """An emitter that counts how many times each event was emitted."""
    def __init__(self) -> None:
        self._handlers: dict = {}
        self._counts: dict = {}

    def on(self, event: str, handler: Callable[..., None]) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def emit(self, event: str, *args: Any) -> None:
        self._counts[event] = self._counts.get(event, 0) + 1
        for h in list(self._handlers.get(event, [])):
            h(*args)

    def emit_count(self, event: str) -> int:
        """How many times emit() was called for the given event.

        Examples:
            >>> e = CountingEmitter(); e.emit('x'); e.emit_count('x')
            1
        """
        return self._counts.get(event, 0)

if __name__ == "__main__":
    e = CountingEmitter()
    e.emit("tick"); e.emit("tick")
    print(e.emit_count("tick"))

