from typing import Iterator

def trie_walk(root: dict) -> Iterator[str]:
    """Walk a dict-style trie, yielding every complete word.

    Args:
        root: The trie root dict.

    Yields:
        Every complete word in the trie.

    Examples:
        >>> root = {"$end": False}
        >>> for w in ['a','ab','b']:
        ...     n = root
        ...     for ch in w: n = n.setdefault(ch, {"$end": False})
        ...     n['$end'] = True
        >>> sorted(trie_walk(root))
        ['a', 'ab', 'b']
    """
    def visit(node: dict, path: str) -> Iterator[str]:
        if node.get("$end"):
            yield path
        for k, v in node.items():
            if k != "$end" and isinstance(v, dict):
                yield from visit(v, path + k)
    yield from visit(root, "")

if __name__ == "__main__":
    root = {"$end": False}
    for w in ["hi", "hit", "him"]:
        n = root
        for ch in w:
            n = n.setdefault(ch, {"$end": False})
        n["$end"] = True
    print(sorted(trie_walk(root)))

